// Calcula métricas de concurrencia por barbero
try {
  const data = $input.all()[0].json;
  const appointments = Array.isArray(data) ? data : (data.data || []);
  const byBarber = {};
  appointments.forEach(a => {
    const barber = a.barber_name || a.staff_name || 'sin_asignar';
    if (!byBarber[barber]) byBarber[barber] = { total: 0, confirmed: 0, no_show: 0, revenue: 0 };
    byBarber[barber].total += 1;
    if (a.status === 'confirmed') byBarber[barber].confirmed += 1;
    if (a.status === 'no_show') byBarber[barber].no_show += 1;
    byBarber[barber].revenue += (a.price || 0);
  });
  return Object.entries(byBarber).map(([barber, m]) => ({ json: { barber, date: $now.toISODate(), ...m } }));
} catch (e) {
  return [{ json: { error: e.message, date: $now.toISODate() } }];
}
